function borrow(a: f64[]): ReadSpan<f64> {
  a.length = 0;
  const v: ReadSpan<f64> = readSpan(a, 0, 0);
  return v;
}
export function entry(): f64 {
  const a: f64[] = [1];
  const old: ReadSpan<f64> = readSpan(a, 0, 0);
  const w: ReadSpan<f64> = borrow(a);
  old.length;
  w.length;
  return 1;
}

